sed -i '/{\/\* Workspace Presets Section \*\/}/i \                <div className="px-3 py-1 text-[10px] font-bold text-gray-400 uppercase tracking-wider">\n                  Live Panels Configuration\n                </div>\n                {[1, 2, 3, 4, 5].map((num) => (\n                  <button\n                    key={`panel-count-${num}`}\n                    onClick={() => { store.setLivePanelCount(num); setActiveMenu(null); }}\n                    className="w-full flex items-center justify-between px-3 py-1 hover:bg-[#323744] hover:text-white text-left"\n                  >\n                    <span>{num} {num === 1 ? '\''Panel'\'' : '\''Panels'\''}</span>\n                    {store.outputGroups.length === num && <Check size={12} className="text-cyan-400 shrink-0 ml-1" />}\n                  </button>\n                ))}\n                <div className="border-t border-[#3b404d] my-1"></div>' src/components/TopToolbar.tsx
